catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }
    g_form.setDisplay('current_section', false);
    g_form.setDisplay('variable1_in_tab1', false);
    g_form.setDisplay('variable2_in_tab1', false);
    g_form.setDisplay('variable1_in_tab2', false);
    g_form.setDisplay('variable2_in_tab2', false);
    g_form.setDisplay('variable1_in_tab3', false);
    g_form.setDisplay('variable2_in_tab3', false);
    g_form.setDisplay('variable1_in_tab4', false);
    g_form.setDisplay('variable2_in_tab4', false);
    g_form.setDisplay('variable1_in_tab5', false);
    g_form.setDisplay('variable2_in_tab5', false);
    //Type appropriate comment here, and begin script below
    if (newValue == '0' || newValue == '1') {
        //display variables for tab 1
        g_form.setDisplay('variable1_in_tab1', true);
        g_form.setDisplay('variable2_in_tab1', true);
    }
    if (newValue == '2') {
        //display variables for tab 2
        g_form.setDisplay('variable1_in_tab2', true);
        g_form.setDisplay('variable2_in_tab2', true);
    } else if (newValue == 3) {
        g_form.setDisplay('variable1_in_tab3', true);
        g_form.setDisplay('variable2_in_tab3', true);
    } else if (newValue == 4) {
        g_form.setDisplay('variable1_in_tab4', true);
        g_form.setDisplay('variable2_in_tab4', true);
    } else if (newValue == 5) {
        g_form.setDisplay('variable1_in_tab5', true);
        g_form.setDisplay('variable2_in_tab5', true);
    }
}
